INSERT INTO `packages` (`id`, `studio_id`, `name`, `description`, `price`, `duration_minutes`, `edited_photos_count`, `included_prints`, `photographer_count`, `included_services`, `terms_and_conditions`, `image`, `is_active`, `created_at`) VALUES
('PKG-2HVYEVVPL', 'ST-FQKCTCGEL', 'Basic Graduation ', '### Graduation Photography\n\nCelebrate your graduation with timeless portraits that capture one of the most important milestones of your academic journey. Our Graduation Photography service is designed to give every graduate a memorable and professional photo experience, from classic toga portraits to creative and personalized poses.\n\nOur studio provides a comfortable and well-prepared setting where graduates can confidently showcase their achievement. Whether you prefer elegant traditional portraits, modern creative shots, or a combination of both, we make sure every photograph reflects your personality, confidence, and accomplishment.\n\n**Our Graduation Photography Service Includes:**\n\n* Professional graduation portraits\n* Toga and graduation-themed setups\n* Multiple poses and portrait styles\n* Professional studio lighting\n* High-quality edited digital photos\n* Optional printed photographs\n* Individual and group graduation portraits\n* Personalized photo concepts and setups\n\nFrom the cap and gown to the proud smile, every moment deserves to be remembered. Let us turn your graduation achievement into photographs you can treasure for years to come.\n', 1500.00, 60, 15, 'None', 1, '', 'No terms specified.', '/api/media/MEDIA-FNSI3YEPI', 1, '2026-09-30 09:05:08'),
('PKG-BLM-01', 'ST-MATERNITY1', 'Bloom & Baby Bundle', '### Maternity + Newborn Combo Package\n\nThe ultimate expectant-mother gift ??? a maternity session now and a newborn session after birth, bundled at a special rate.\n\n**What\'s Included:**\n- Maternity Glow Session (28???36 weeks)\n- Newborn Dreamscape Session (within 2 weeks of birth)\n- 25 combined edited high-resolution digital photos\n- 1 printed 8R maternity portrait\n- 1 printed 8R newborn portrait\n- 1 printed 5R parent-and-baby photo\n- Complimentary birth announcement digital card design\n\nBook the combo and save ???1,000 vs. booking separately.', 4500.00, 210, 25, '1 printed 8R maternity,1 printed 8R newborn,1 printed 5R parent-baby', 1, 'Maternity Glow Session,Newborn Dreamscape Session', 'A 50% deposit is required at booking. Maternity session scheduled first; newborn session date confirmed after birth. Rescheduling allowed with 48 hours notice. Prints ready 7 business days after each session.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-BLM-02', 'ST-MATERNITY1', 'First Year Journey Package', '### Baby\'s First Year Milestone Package\n\nDocument every milestone of your baby\'s first 12 months with a full year of monthly mini sessions.\n\n**What\'s Included:**\n- 12 Monthly Milestone Mini Sessions (1 per month)\n- 8 edited photos per session (96 total across the year)\n- Milestone themed props included each month\n- End-of-year digital album compilation\n- 1 printed 10R year-in-review collage portrait\n\nA beautiful record of how much they grow ??? month by month.', 15000.00, 720, 96, '1 printed 10R year-in-review collage', 1, 'Monthly Milestone Mini Session', 'Full year package billed as ???15,000 upfront or 3 installments of ???5,500. Sessions must be used within 13 months of first booking. Unused sessions are non-refundable. Rescheduling each month with 24 hours notice.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-ELLA-BABY-01', 'ST-FQKCTCGEL', 'Baby Bloom Package', '### Newborn & Baby Portrait Package\n\nA gentle and beautiful package for your newest family member ??? capturing those irreplaceable early weeks and months.\n\n**What\'s Included:**\n- 1 baby subject (0???12 months)\n- Wraps, baskets, and floral props provided\n- Parent or sibling inclusion shots\n- 15 edited high-resolution digital photos\n- 1 printed 8R baby portrait\n- 1 printed 5R parent-and-baby photo\n\nThe session pace follows the baby\'s comfort and feeding schedule ??? no rush, only love.', 2800.00, 90, 15, '1 printed 8R baby portrait,1 printed 5R parent-baby photo', 1, 'Newborn & Baby Session', 'A 30% non-refundable deposit is required. Session scheduling is flexible around feeding times. The studio will be kept warm for the baby. Prints ready within 5???7 business days. Digital files delivered within 3 business days.', '/api/media/MEDIA-BT6DYUX7Z', 1, '2026-10-02 07:27:20'),
('PKG-ELLA-BABY-02', 'ST-FQKCTCGEL', 'Milestone Magic Package', '### Cake Smash & Milestone Package\n\nThe ultimate first birthday celebration shoot ??? fun, messy, and absolutely unforgettable.\n\n**What\'s Included:**\n- 1 baby/toddler subject (up to 3 years old)\n- Themed backdrop and balloon setup\n- Cake smash session + before/after clean-up shots\n- 20 edited high-resolution digital photos\n- 1 printed 8R milestone portrait\n- 1 printed 5R cake smash highlight\n- Digital slideshow teaser (10 photos)\n\nParents and siblings are welcome to join for group shots at the end.', 3500.00, 90, 20, '1 printed 8R milestone portrait,1 printed 5R cake smash photo', 1, 'Milestone Cake Smash Session', 'A 50% non-refundable deposit is required. Cake can be provided by the studio (basic) or brought by the client. Bring a change of clothes and towel. Theme/color scheme must be confirmed 3 days before the session. Prints ready within 7 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-FAM-01', 'ST-FQKCTCGEL', 'Family Memories Package', '### Family Portrait Package\n\nA warm and beautiful studio session for your family ??? capturing the moments that matter most in a professional setting.\n\n**What\'s Included:**\n- Up to 5 family members, 1 outfit change\n- 12 edited high-resolution digital photos\n- 1 printed 8R family portrait\n- 2 printed 5R individual/sub-group portraits\n- Professional lighting and backdrop selection\n\nA treasure your family will look back on for years.', 2500.00, 90, 12, '1 printed 8R family portrait,2 printed 5R portraits', 1, 'Family Portrait Session', 'A 30% non-refundable deposit is required. Rescheduling with at least 48 hours notice. Additional members beyond 5 are charged at ???200 per person. Prints ready within 5???7 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-FAM-02', 'ST-FQKCTCGEL', 'Grand Family Reunion Package', '### Extended Family Portrait Package\n\nA full-scale studio session for the whole clan ??? reunions, anniversaries, or simply gathering the family together for a keepsake portrait everyone can cherish.\n\n**What\'s Included:**\n- 6 to 15 family members\n- 2 group configurations (full group + sub-groups)\n- 20 edited high-resolution digital photos\n- 1 printed 10R large family portrait\n- 4 printed 5R sub-group portraits\n\nFor groups over 15, contact us for a custom arrangement.', 4000.00, 120, 20, '1 printed 10R large portrait,4 printed 5R portraits', 2, 'Extended Family Session', 'A 50% non-refundable deposit is required. Book at least 1 week in advance. Outfit coordination is the responsibility of the client. Additional members beyond 15 are charged at ???300 per person. Prints ready within 7 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-PORT-01', 'ST-FQKCTCGEL', 'Portrait Essentials', '### Individual Portrait Package\n\nA polished, all-in-one portrait experience for individuals who want professional quality without the fuss.\n\n**What\'s Included:**\n- 1 subject, up to 2 outfit changes\n- 10 edited high-resolution digital photos\n- 1 printed 5R portrait\n- Choice of 3 backdrop colors\n- Professional retouching\n\nIdeal for professional headshots, LinkedIn profiles, and personal branding materials.', 1200.00, 60, 10, '1 printed 5R portrait', 1, 'Individual Portrait Session', 'A 30% non-refundable booking deposit is required to secure your schedule. Full payment is due on the day of the session. Rescheduling must be requested at least 48 hours in advance. No-shows forfeit the deposit.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-PORT-02', 'ST-FQKCTCGEL', 'Portrait Duo Bundle', '### Couple Portrait Package\n\nA complete couple portrait experience ??? perfect for anniversaries, pre-nuptial teasers, or simply celebrating your relationship.\n\n**What\'s Included:**\n- 2 subjects, up to 2 outfit changes\n- 15 edited high-resolution digital photos\n- 2 printed 5R couple portraits\n- 1 printed 8R couple photo\n- Choice of 3 backdrop and lighting moods\n\nA beautiful way to document your love story.', 1800.00, 75, 15, '2 printed 5R portraits,1 printed 8R photo', 1, 'Couple Portrait Session', 'A 30% non-refundable booking deposit is required. Rescheduling must be requested at least 48 hours in advance. Prints are released 3???5 business days after the session. Digital files are delivered within 2 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-PRD-01', 'ST-FQKCTCGEL', 'Product Starter Pack', '### Product Photography Starter\n\nClean, professional product images ready for your online store or catalog ??? no extra fuss, just results.\n\n**What\'s Included:**\n- Up to 10 product items\n- White and black backdrop options\n- Flat lay and upright angle shots\n- 10 edited high-resolution digital photos\n- Delivered via digital download\n\nPerfect for Shopee, Lazada, and Instagram sellers launching or refreshing their product listings.', 2000.00, 60, 10, 'None', 1, 'Product Still Photography', 'Full payment required upon booking. Bring products clean and ready. Session limited to 10 items. Additional items charged at ???100 per item. Digital files delivered within 3 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-PRD-02', 'ST-FQKCTCGEL', 'Brand Content Bundle', '### Brand Content Photography Package\n\nA comprehensive product and lifestyle content shoot for brands that need both clean cut-out images and editorial-style lifestyle shots in one session.\n\n**What\'s Included:**\n- Up to 5 products (still) + up to 3 products (lifestyle)\n- White backdrop still shots + 1 styled scene setup\n- 20 edited high-resolution digital photos total\n- Delivered via digital download\n\nIdeal for brand owners, marketing teams, and content creators who need a variety of images for campaigns.', 4000.00, 150, 20, 'None', 1, 'Product Still Photography,Lifestyle Product Session', 'A 50% deposit is required at booking. Final payment on session day. Props and set styling based on agreed brief. Additional products charged at ???200 per item. Files delivered within 5 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-WED-01', 'ST-FQKCTCGEL', 'Pre-Wedding Silver Package', '### Pre-Wedding Studio Package\n\nAn intimate and romantic pre-wedding portrait session for couples who want stunning studio images before the big day.\n\n**What\'s Included:**\n- 2 subjects (couple), up to 2 outfit changes\n- 15 edited high-resolution digital photos\n- 1 printed 8R couple photo\n- 1 printed 5R portrait each\n- Soft romantic and dramatic lighting setups\n\nImages are perfect for wedding invitations, social announcements, and display at the reception.', 3500.00, 90, 15, '1 printed 8R photo,2 printed 5R portraits', 1, 'Pre-Wedding Studio Session', 'A 50% non-refundable booking deposit is required. Final payment is due on session day. Rescheduling allowed once with at least 72 hours notice. Digital files delivered within 5 business days. Printed products ready within 7 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-ELLA-WED-02', 'ST-FQKCTCGEL', 'Bridal Gold Package', '### Bridal Portrait Package\n\nAn elegant, full bridal portrait experience ??? celebrating the bride in all her beauty before the wedding day.\n\n**What\'s Included:**\n- 1 subject (bride), up to 2 gown/styling changes\n- 20 edited high-resolution digital photos\n- 2 printed 8R bridal portraits\n- 1 printed 10R framed bridal portrait\n- Soft romantic lighting and multiple backdrops\n\nThe perfect wedding keepsake and a wonderful surprise display for the reception.', 4500.00, 90, 20, '2 printed 8R portraits,1 framed 10R bridal portrait', 1, 'Bridal Portrait Session', 'A 50% non-refundable booking deposit is required. Rescheduling allowed once with at least 72 hours notice. Hair and makeup must be arranged by the client before arrival. Printed products ready within 7???10 business days.', NULL, 1, '2026-10-02 07:27:20'),
('PKG-FDL-01', 'ST-FOODLENS1', 'Restaurant Starter Pack', '### Restaurant Menu Photography Package\n\nEverything a new or growing restaurant needs to launch professional, appetite-triggering menu photos.\n\n**What\'s Included:**\n- Menu Photography Session (up to 15 items)\n- Beverage & Drinks Shoot (up to 5 drinks)\n- 20 edited high-resolution digital photos total\n- Delivered via digital download in 3 business days\n- Formatted for print menu and food delivery app (GrabFood, Foodpanda)\n\nLaunch your menu with photos that sell.', 4000.00, 240, 20, 'None', 1, 'Menu Photography Session,Beverage & Drinks Shoot', 'Full payment required upon booking. Food must arrive fresh on session day. Rescheduling with 48 hours notice. Additional items beyond package limit charged at ???150 per item. Files delivered within 3 business days.', NULL, 1, '2026-10-02 08:39:18'),
('PKG-FDL-02', 'ST-FOODLENS1', 'Brand Content Full Day', '### Food Brand Full Content Day\n\nA complete, full-day food content shoot for food brands, CPG companies, and F&B businesses ??? covering all your content needs in one day.\n\n**What\'s Included:**\n- Styled Food Editorial (up to 8 hero setups)\n- Menu Photography (up to 10 additional items)\n- Beverage Photography (up to 6 drinks)\n- 40 edited high-resolution digital photos\n- Commercial usage rights\n- Delivered within 5 business days\n- Bonus: 5 vertical crop edits for Instagram Stories/Reels\n\nOne power shoot day, one month of content.', 9000.00, 480, 40, 'None', 2, 'Styled Food Editorial,Menu Photography Session,Beverage & Drinks Shoot', '50% deposit required. Mood board and brief due 5 days before. Additional setups beyond package limit at ???600 each. Commercial usage rights granted upon full payment. Files delivered within 5 business days.', NULL, 1, '2026-10-02 08:39:18'),
('PKG-FSH-01', 'ST-FASHPHOTO', 'Rising Model Package', '### Model Portfolio Starter Package\n\nEverything a new or emerging model needs to build a compelling, professional portfolio.\n\n**What\'s Included:**\n- Full Model Portfolio Shoot (3 looks)\n- 20 edited high-resolution digital photos\n- 1 printed 8R portfolio highlight photo\n- Basic retouching and skin smoothing\n- Digital file delivery in 5 business days\n- 30-minute pre-shoot posing coaching session\n\nStart your modeling career with images that get you noticed.', 4500.00, 180, 20, '1 printed 8R portfolio photo', 1, 'Model Portfolio Shoot', 'A 50% deposit is required. No refunds within 48 hours of session. Clothes and styling are the model\'s responsibility unless agreed otherwise. Usage rights for portfolio and personal social media only.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-FSH-02', 'ST-FASHPHOTO', 'Brand Campaign Bundle', '### Full Brand Campaign Photography Package\n\nA complete campaign shoot package for clothing brands, beauty labels, and lifestyle businesses ready to make a statement.\n\n**What\'s Included:**\n- Brand Lookbook Shoot (up to 5 looks per model)\n- Creative Concept Editorial (1 hero campaign set)\n- 1 model included (additional models at ???1,500 each)\n- 35 edited high-resolution digital photos total\n- Commercial usage rights for print and digital\n- Delivered within 7 business days\n- Complimentary 1-page digital media kit layout\n\nElevate your brand\'s visual identity in one powerful shoot day.', 12000.00, 480, 35, 'None', 2, 'Brand Lookbook Shoot,Creative Concept Editorial', '50% deposit required. Creative brief and mood board must be submitted 1 week before. Commercial usage rights granted upon full payment. Additional models at ???1,500 each. Cancellation within 72 hours forfeits deposit.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-LMN-01', 'ST-LUMINOS01', 'Debut Royale Package', '### Debut Royale Photography Package\n\nThe complete debut photography experience ??? from preparation portraits to the cotillion and farewell shots.\n\n**What\'s Included:**\n- Up to 6 hours of coverage\n- Solo, group, cotillion, and candid portraits\n- 18 Roses and 18 Candles styled shots\n- 40 edited high-resolution digital photos\n- 1 printed 10R framed debut portrait\n- 4 printed 5R individual portraits\n- Online gallery link\n\nEvery debutante deserves to feel like royalty.', 5500.00, 360, 40, '1 framed 10R portrait,4 printed 5R portraits', 2, 'Birthday Debut Coverage', 'A 50% non-refundable deposit is required. Book at least 3 weeks in advance. Rescheduling allowed once with 1 week notice. Additional hours billed at ???800/hour. Digital files delivered within 7 business days.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-LMN-02', 'ST-LUMINOS01', 'Corporate Prestige Pack', '### Corporate Event Photography Package\n\nA professional, fully-managed corporate portrait day for your entire team.\n\n**What\'s Included:**\n- Up to 4 hours studio or on-site coverage\n- Individual headshots for up to 30 employees\n- Up to 3 team/department group shots\n- 35 edited high-resolution digital photos\n- Each employee receives their own digital headshot\n- Delivered via shared drive within 3 business days\n\nElevate your company\'s brand image with polished, consistent team portraits.', 8000.00, 240, 35, 'None', 2, 'Corporate Event Studio Portraits', '50% deposit required upon booking. Final headcount must be confirmed 3 days prior. On-site setup fee of ???500 applies if outside Cainta. Cancellation within 48 hours forfeits deposit. Files delivered within 3 business days.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-PAW-01', 'ST-PETCLICK1', 'Paw Portrait Package', '### Pet Portrait Bundle\n\nA comprehensive portrait package to capture your pet at their most adorable.\n\n**What\'s Included:**\n- Pet Solo Portrait Session (1 pet)\n- 15 edited high-resolution digital photos\n- 1 printed 8R pet portrait\n- 2 printed 5R pet photos\n- Printed pet ID card (wallet-size)\n\nThe perfect gift for any pet parent.', 2500.00, 60, 15, '1 printed 8R portrait,2 printed 5R photos,1 wallet-size pet ID card', 1, 'Pet Solo Portrait', 'A 30% deposit is required. Pets must be vaccinated. Session rescheduling with 24 hours notice. Treats and toys provided but clients may bring their own. Studio not liable for pet behavior beyond our standard care.', NULL, 1, '2026-10-02 08:34:55'),
('PKG-PAW-02', 'ST-PETCLICK1', 'Fur Family Complete Pack', '### Pet & Family Complete Package\n\nCapture the complete picture ??? your whole family, fur babies included.\n\n**What\'s Included:**\n- Pet Solo Portrait Session\n- Pet & Family Portrait Session\n- Pet Birthday Bash (bonus themed set)\n- 25 edited high-resolution digital photos total\n- 1 printed 10R family-and-pet portrait\n- 2 printed 5R individual pet portraits\n- Digital pet birthday card design\n\nThree sessions bundled into one special day.', 5500.00, 225, 25, '1 printed 10R family portrait,2 printed 5R pet portraits', 2, 'Pet Solo Portrait,Pet & Family Portrait,Pet Birthday Bash Session', '50% deposit required. All pets must be vaccinated. Rescheduling with 48 hours notice. Full day sessions must be completed within one day. Prints and digital files delivered within 7 business days.', NULL, 1, '2026-10-02 08:34:55'),
('PKG-SNC-01', 'ST-SNAPCRAFT', 'SnapCraft Solo Bundle', '### Solo Self-Shoot Bundle\n\nThe perfect starter pack for individual content creators and social media enthusiasts.\n\n**What\'s Included:**\n- 2 hours studio access (solo or +1)\n- Access to 2 themed sets\n- Full lighting setup\n- Free props and accessories\n- 10 complimentary edited digital photos by our in-house editor\n- Printed 5R highlight photo\n\nGet two hours of creative freedom plus a professional touch on your best shots.', 1500.00, 120, 10, '1 printed 5R highlight photo', 1, '1-Hour Solo Self-Shoot', 'Full payment required at booking. Rescheduling allowed with 24 hours notice. No refunds for no-shows. Maximum 2 people. Studio props must be handled with care ??? damage fees apply.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-SNC-02', 'ST-SNAPCRAFT', 'Creator Pro Day Pass', '### Content Creator Full-Day Bundle\n\nFor creators who need maximum time, maximum sets, and maximum output.\n\n**What\'s Included:**\n- 8 hours studio access (up to 4 people)\n- Unlimited set changes across all themed sets\n- Full lighting rig access (strobes, LEDs, ring lights)\n- Wardrobe rack and dressing room\n- Studio assistant for the day\n- 20 complimentary edited digital photos\n- 2 printed 5R photos\n\nThe ultimate studio day for brands, creators, and agencies.', 5500.00, 480, 20, '2 printed 5R photos', 1, 'Content Creator Package (Half Day),Group Self-Shoot (up to 6 pax)', '50% deposit required. Full payment due on session day. Maximum 4 people included ??? extra at ???200/pax. Rescheduling with 48 hours notice. Damage to props or sets charged at replacement cost. Studio closes at 10 PM.', NULL, 1, '2026-10-02 08:34:54'),
('PKG-VOW-01', 'ST-COUPLECO1', 'Sweethearts Package', '### Engagement + Anniversary Bundle\n\nA romantic bundle celebrating both your engagement and your love story ??? two sessions, one unforgettable memory.\n\n**What\'s Included:**\n- Engagement Studio Session\n- Styled Anniversary Session\n- 20 combined edited high-resolution digital photos\n- 1 printed 10R couple portrait\n- 2 printed 5R portraits\n- Complimentary digital save-the-date card design\n\nA beautiful way to mark two milestones in one.', 6000.00, 180, 20, '1 printed 10R couple portrait,2 printed 5R portraits', 1, 'Engagement Studio Session,Styled Anniversary Session', '50% deposit required. Sessions can be taken on the same day or separate days. Rescheduling with 48 hours notice. Digital save-the-date design delivered within 5 business days. Prints ready in 7 business days.', NULL, 1, '2026-10-02 08:41:26'),
('PKG-VOW-02', 'ST-COUPLECO1', 'The Vow Signature Package', '### Pre-Nuptial Signature Package\n\nThe ultimate pre-wedding studio experience ??? cinematic, grand, and deeply personal.\n\n**What\'s Included:**\n- Pre-Nuptial Cinematic Session (4 styled scenes)\n- Engagement Studio Session (bonus)\n- 35 edited high-resolution digital photos\n- 1 printed 12x16 canvas couple portrait\n- 1 printed 10R framed hero photo\n- 4 printed 5R portraits\n- Complimentary wedding invitation digital template\n- Same-day sneak peek (5 unedited previews)\n\nFor the couple who wants nothing less than extraordinary.', 12000.00, 390, 35, '1 canvas 12x16 portrait,1 framed 10R photo,4 printed 5R portraits', 2, 'Pre-Nuptial Cinematic Session,Engagement Studio Session', '50% non-refundable deposit required. Pre-shoot consultation mandatory. Hair and makeup arranged by clients. Rescheduling with 1 week notice. Canvas and framed prints ready in 10 business days. Digital files within 7 business days.', NULL, 1, '2026-10-02 08:41:26');
