INSERT INTO `reviews` (`id`, `studio_id`, `customer_id`, `customer_name`, `booking_id`, `rating`, `comment`, `status`, `reply`, `reply_at`, `created_at`) VALUES
('REV-BLM-H001', 'ST-MATERNITY1', 'CUST-A022', 'Carlo Santos', 'BK-BLM-H001', 5, 'Such a warm and welcoming studio. My wife felt so beautiful and comfortable during the maternity shoot. Photos are stunning!', 'approved', 'Thank you Carlo! We are so glad your wife had a wonderful experience. Congratulations on your growing family!', '2025-04-08 01:00:00', '2025-04-07 02:00:00'),
('REV-BLM-H002', 'ST-MATERNITY1', 'CUST-A023', 'Nina Castro', 'BK-BLM-H002', 5, 'The newborn session was handled with so much care and love. Our baby was safe and comfortable the whole time. Best investment we made!', 'approved', 'Thank you Nina! Your little one was an absolute sweetheart. We treasure every newborn session we get to do.', '2025-06-17 01:00:00', '2025-06-16 02:00:00'),
('REV-BLM-H003', 'ST-MATERNITY1', 'CUST-A024', 'Rico Dela Torre', 'BK-BLM-H003', 4, 'Milestone session was well-organized. Props were adorable. Would love more backdrop options but overall very satisfied.', 'approved', 'Thank you Rico! We are always adding new backdrop options ??? we hope to show you next time!', '2025-08-12 01:00:00', '2025-08-11 02:00:00'),
('REV-ELLA-H001', 'ST-FQKCTCGEL', 'CUST-A001', 'Ana Reyes', 'BK-ELLA-H001', 5, 'Excellent portrait session! The photographer was patient and the results were stunning. Will definitely book again.', 'approved', 'Thank you so much Ana! We are so happy you loved your portraits. See you next time!', '2025-02-18 01:00:00', '2025-02-17 02:00:00'),
('REV-ELLA-H002', 'ST-FQKCTCGEL', 'CUST-A002', 'Jose Santos', 'BK-ELLA-H002', 5, 'Great graduation photos! My son loved all of them. The backdrop choices were perfect.', 'approved', 'Congratulations to your son Jose! Thank you for trusting us with his big day.', '2025-03-23 01:00:00', '2025-03-22 02:00:00'),
('REV-ELLA-H003', 'ST-FQKCTCGEL', 'CUST-A003', 'Maria Dela Cruz', 'BK-ELLA-H003', 4, 'Beautiful family photos. The studio was clean and comfortable. Minor wait time but worth it.', 'approved', 'Thank you Maria! We appreciate your patience and we are glad your family loved the results.', '2025-05-13 01:00:00', '2025-05-12 02:00:00'),
('REV-ELLA-H005', 'ST-FQKCTCGEL', 'CUST-A005', 'Liza Fernandez', 'BK-ELLA-H005', 5, 'They were so gentle with my newborn. The studio was warm and safe. Absolutely recommend for new moms!', 'approved', 'Thank you Liza! We love photographing newborns ??? your little one was absolutely precious.', '2025-09-10 01:00:00', '2025-09-09 02:00:00'),
('REV-ELLA-H007', 'ST-FQKCTCGEL', 'CUST-A007', 'Claire Mendoza', 'BK-ELLA-H007', 5, 'Our anniversary couple portraits are gorgeous. Perfect lighting and great set options!', 'approved', 'Thank you Claire! Happy anniversary to you both ??? so glad we could capture this milestone.', '2026-01-20 01:00:00', '2026-01-19 02:00:00'),
('REV-ELLA-H008', 'ST-FQKCTCGEL', 'CUST-A008', 'Kevin Torres', 'BK-ELLA-H008', 5, 'Best cake smash photos! My baby had so much fun and the team handled everything perfectly.', 'approved', 'Thank you Kevin! Cake smash shoots are our favorite ??? so happy your little one enjoyed it!', '2026-03-24 01:00:00', '2026-03-23 02:00:00'),
('REV-FDL-H001', 'ST-FOODLENS1', 'CUST-A003', 'Maria Dela Cruz', 'BK-FDL-H001', 5, 'Our menu photos look absolutely delicious! Orders increased significantly after we updated our GrabFood photos. This studio is the real deal.', 'approved', 'Thank you Maria! Nothing makes us happier than helping businesses grow through great food photography!', '2025-04-22 01:00:00', '2025-04-21 02:00:00'),
('REV-FDL-H002', 'ST-FOODLENS1', 'CUST-A006', 'Marco Villanueva', 'BK-FDL-H002', 5, 'The styled food editorial made our cafe brand look like it belongs in a magazine. Incredible eye for detail and styling.', 'approved', 'Thank you Marco! Your cafe concept was a joy to work with ??? beautiful brand, beautiful food!', '2025-07-20 01:00:00', '2025-07-19 02:00:00'),
('REV-FDL-H004', 'ST-FOODLENS1', 'CUST-A020', 'Ben Navarro', 'BK-FDL-H004', 5, 'Restaurant starter pack was the best investment for our new branch launch. Every dish looked mouthwatering. Highly recommended!', 'approved', 'Thank you Ben! Congratulations on your new branch launch ??? wishing your restaurant great success!', '2026-01-14 01:00:00', '2026-01-13 02:00:00'),
('REV-FSH-H001', 'ST-FASHPHOTO', 'CUST-A028', 'Alex Buenaventura', 'BK-FSH-H001', 5, 'My model portfolio looks incredible! The photographer knew exactly how to bring out the best in every shot. 100% professional.', 'approved', 'Thank you Alex! It was a pleasure working with you. Your portfolio is going to open so many doors!', '2025-03-10 01:00:00', '2025-03-09 02:00:00'),
('REV-FSH-H002', 'ST-FASHPHOTO', 'CUST-A029', 'Mia Evangelista', 'BK-FSH-H002', 5, 'Our brand lookbook turned out absolutely stunning. The team understood our aesthetic perfectly. Will book again for the next collection!', 'approved', 'Thank you Mia! We loved bringing your brand vision to life ??? looking forward to your next collection!', '2025-06-14 01:00:00', '2025-06-13 02:00:00'),
('REV-FSH-H003', 'ST-FASHPHOTO', 'CUST-A030', 'Leo Madriaga', 'BK-FSH-H003', 5, 'The creative editorial concept was beyond what I imagined. The set design was out of this world. Absolutely world-class work!', 'approved', 'Thank you Leo! Creative concepts are our passion ??? so glad we could bring your vision to life!', '2025-09-22 01:00:00', '2025-09-21 02:00:00'),
('REV-LMN-H001', 'ST-LUMINOS01', 'CUST-A011', 'Patricia Ramos', 'BK-LMN-H001', 5, 'The kids absolutely loved the themed backdrop! Photos came out vibrant and full of energy. Great team!', 'approved', 'Thank you Patricia! We love doing kiddie parties ??? the joy on the children\'s faces makes it all worthwhile.', '2025-05-20 01:00:00', '2025-05-19 02:00:00'),
('REV-LMN-H002', 'ST-LUMINOS01', 'CUST-A012', 'Joseph Cruz', 'BK-LMN-H002', 5, 'My daughter\'s debut photos were absolutely magical. The team captured every moment beautifully.', 'approved', 'Thank you Joseph! Debuts are always so special ??? congratulations to your daughter on her 18th!', '2025-07-28 01:00:00', '2025-07-27 02:00:00'),
('REV-LMN-H003', 'ST-LUMINOS01', 'CUST-A013', 'Rachel Lim', 'BK-LMN-H003', 4, 'Very professional team. Our corporate headshots were delivered on time and look polished. Minor communication delay but overall great experience.', 'approved', 'Thank you Rachel! We appreciate the feedback on communication and will continue to improve. Glad you loved the headshots!', '2025-10-18 01:00:00', '2025-10-17 02:00:00'),
('REV-LMN-H005', 'ST-LUMINOS01', 'CUST-A015', 'Sophia Chan', 'BK-LMN-H005', 5, 'Valentines debut theme was dreamy! The photographer was creative and the photos exceeded my expectations.', 'approved', 'Thank you Sophia! So happy your debut had that magical valentines feel. You looked like royalty!', '2026-02-25 01:00:00', '2026-02-24 02:00:00'),
('REV-NCVG6YD2U', 'ST-FQKCTCGEL', 'CUST-0TYLOW9TN', 'mercymonteza7@gmail.com', 'BK-2026-ACBK60XY8', 5, 'goods', 'pending', 'thanks', '2026-10-01 10:51:06', '2026-10-01 10:49:48'),
('REV-PAW-H001', 'ST-PETCLICK1', 'CUST-A037', 'Lea Gonzales', 'BK-PAW-H001', 5, 'My golden retriever looked like a supermodel! The team was so good with animals. Highly recommend PawClick to every pet owner!', 'approved', 'Thank you Lea! Your golden was an absolute natural in front of the camera. Come back soon!', '2025-07-08 01:00:00', '2025-07-07 02:00:00'),
('REV-PAW-H002', 'ST-PETCLICK1', 'CUST-A038', 'Nico Reyes', 'BK-PAW-H002', 5, 'Family and dog portrait turned out beautifully. My dog was calm and happy the whole time. The team made it fun for everyone!', 'approved', 'Thank you Nico! Family and pet sessions are always our favorite. Your dog was so well-behaved!', '2025-09-16 01:00:00', '2025-09-15 02:00:00'),
('REV-PAW-H004', 'ST-PETCLICK1', 'CUST-A013', 'Rachel Lim', 'BK-PAW-H004', 5, 'Shih tzu portrait bundle was worth every peso! The framed photo now hangs in our living room. Amazing quality!', 'approved', 'Thank you Rachel! Framed pets belong in living rooms ??? your shih tzu looks like a proper VIP!', '2026-02-10 01:00:00', '2026-02-09 02:00:00'),
('REV-SNC-H001', 'ST-SNAPCRAFT', 'CUST-A017', 'Jennie Flores', 'BK-SNC-H001', 5, 'Amazing self-shoot studio! The setups are gorgeous and the lighting is perfect. Already booked again.', 'approved', 'Thank you Jennie! Your content looked amazing ??? can\'t wait to have you back!', '2025-06-30 01:00:00', '2025-06-29 02:00:00'),
('REV-SNC-H002', 'ST-SNAPCRAFT', 'CUST-A018', 'Don Pascual', 'BK-SNC-H002', 5, 'Brought my squad and we had the best time! Sets were unique and props were fun. Great value for money.', 'approved', 'Thank you Don! Barkada shoots are the best ??? come back anytime with the whole crew!', '2025-08-18 01:00:00', '2025-08-17 02:00:00'),
('REV-SNC-H003', 'ST-SNAPCRAFT', 'CUST-A019', 'Tricia Santos', 'BK-SNC-H003', 5, 'Full day content shoot was incredibly productive. Got 3 months of content in one day. Highly recommend Creator Pro pass!', 'approved', 'Thank you Tricia! That is exactly what the Creator Pro pass is designed for. See you next quarter!', '2025-10-28 01:00:00', '2025-10-27 02:00:00'),
('REV-VOW-H001', 'ST-COUPLECO1', 'CUST-A002', 'Jose Santos', 'BK-VOW-H001', 5, 'Our engagement photos are absolutely romantic and timeless. The lighting, the poses, the editing ??? everything was perfect!', 'approved', 'Thank you Jose! Congratulations on your engagement ??? wishing you both a lifetime of love!', '2025-02-24 01:00:00', '2025-02-23 02:00:00'),
('REV-VOW-H002', 'ST-COUPLECO1', 'CUST-A015', 'Sophia Chan', 'BK-VOW-H002', 5, 'The Vow Studio delivered the most cinematic pre-nuptial photos we have ever seen. Exceeded every expectation. Worth every peso!', 'approved', 'Thank you Sophia! It was an honor to photograph your love story. We wish you a beautiful wedding day!', '2025-05-26 01:00:00', '2025-05-25 02:00:00'),
('REV-VOW-H003', 'ST-COUPLECO1', 'CUST-A016', 'Miguel Ocampo', 'BK-VOW-H003', 5, 'Our 5th anniversary session brought back all the magic of our wedding day. The team made us feel so comfortable and the results were breathtaking.', 'approved', 'Thank you Miguel! Happy 5th anniversary ??? here is to many more years of love and beautiful portraits!', '2025-09-02 01:00:00', '2025-09-01 02:00:00'),
('REV-VOW-H005', 'ST-COUPLECO1', 'CUST-A026', 'Ivan Magpayo', 'BK-VOW-H005', 5, 'Pre-nuptial shoot was beyond cinematic. Four scenes, all perfect. We cried looking at the final photos. The Vow Studio is truly world-class.', 'approved', 'Thank you Ivan! Your reaction means everything to us. We cannot wait to see photos from your wedding day!', '2026-03-02 01:00:00', '2026-03-01 02:00:00'),
('REV-WBAZCIX3U', 'ST-FQKCTCGEL', 'CUST-0TYLOW9TN', 'mercymonteza7@gmail.com', 'BK-2026-TVWXINI2A', 4, 'googds', 'pending', NULL, NULL, '2026-10-01 10:49:57');
INSERT INTO `services` (`id`, `studio_id`, `name`, `description`, `category`, `base_price`, `duration_minutes`, `image`, `is_active`, `available_days`, `available_slots`, `requirements`, `created_at`) VALUES
('SRV-0302EY1OD', 'ST-FQKCTCGEL', 'Graduation', '🎓 Basic Graduation Package\n\nCelebrate your graduation with a simple yet memorable studio portrait session designed to capture your achievement and special milestone.\n\nPackage Includes:\n\n* 1 student\n* 2 professional graduation poses\n* 1 toga setup\n* Professional studio lighting and backdrop\n* Basic photo enhancement and retouching\n* 2 printed 5R graduation photos\n* 2 high-resolution digital copies\n\nPerfect for graduates who want clean, professional, and timeless graduation portraits to keep and share with family and friends.\n', 'Graduation Shoots', 500.00, 60, '[\"/api/media/MEDIA-F2HSWVBO4\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,10:30 AM,01:00 PM,02:30 PM,04:00 PM', 'Arrive 10 minutes early', '2026-09-30 09:02:59'),
('SRV-BLM-01', 'ST-MATERNITY1', 'Maternity Glow Session', '???? Maternity Glow Session\n\nAn elegant and intimate studio session celebrating your pregnancy ??? capturing the beauty of motherhood before your little one arrives.\n\nIncludes:\n* 1 mom subject (partner/siblings welcome for subset of shots)\n* Soft draping, floral, and wrap styling\n* 10 edited high-resolution digital photos\n* 1 printed 8R maternity portrait\n\nBest scheduled between 28???36 weeks of pregnancy.', 'Maternity Photography', 2500.00, 90, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,11:00 AM,02:00 PM', 'Best at 28-36 weeks of pregnancy,Bring a comfortable robe or gown,Partner and kids are welcome for some shots', '2026-10-02 08:34:54'),
('SRV-BLM-02', 'ST-MATERNITY1', 'Newborn Dreamscape Session', '???? Newborn Dreamscape Session\n\nA safe and beautifully styled newborn session creating dreamy, timeless portraits of your newest family member.\n\nIncludes:\n* Baby in wraps, baskets, and floral setups\n* Sibling and parent inclusion shots\n* 15 edited high-resolution digital photos\n* 1 printed 8R newborn portrait\n* 1 printed 5R parent-newborn photo\n\nBest within the first 2 weeks of birth. Session is fully paced around baby\'s comfort.', 'Baby & Milestone Photography', 3000.00, 120, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,12:00 PM,03:00 PM', 'Ideal within first 2 weeks of birth,Bring extra milk/formula and diapers,Studio is kept warm for baby comfort,Allow 2-3 hours ??? we never rush a newborn', '2026-10-02 08:34:54'),
('SRV-BLM-03', 'ST-MATERNITY1', 'Monthly Milestone Mini Session', '???? Monthly Milestone Mini Session\n\nDocument every precious stage of your baby\'s first year with our monthly milestone mini sessions.\n\nIncludes:\n* Baby age props (1 month to 12 months milestone boards)\n* Seasonal or themed backdrop\n* 8 edited high-resolution digital photos\n* Digital delivery within 3 business days\n\nAvailable as a one-time session or sign up for the full 12-month series.', 'Baby & Milestone Photography', 1500.00, 60, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,10:30 AM,12:00 PM,01:30 PM,03:00 PM', 'Bring baby\'s favorite comfort toy,Dress baby in the outfit you want immortalized,Feed baby before the session for best mood', '2026-10-02 08:34:54'),
('SRV-ELLA-BABY-01', 'ST-FQKCTCGEL', 'Newborn & Baby Session', '???? Newborn & Baby Portrait\n\nA gentle, safe, and beautifully styled session for newborns (0???3 months) and babies up to 12 months ??? capturing those tiny, fleeting moments forever.\n\nIncludes:\n* 1 baby subject\n* Soft wraps, props, and basket setups provided\n* Parent inclusion shots available\n* 10 edited high-resolution digital photos\n* 1 printed 5R baby portrait\n\nSession is paced around the baby\'s comfort and feeding schedule. Safety is always our top priority.', 'Baby & Milestone Photography', 2000.00, 90, '[\"/api/media/MEDIA-S4KX5TX52\"]', 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,11:00 AM,01:00 PM', 'Schedule session within the first 2 weeks of birth for best results,Bring extra milk or formula and diapers,Studio will be kept warm for baby comfort', '2026-10-02 07:27:20'),
('SRV-ELLA-BABY-02', 'ST-FQKCTCGEL', 'Milestone Cake Smash Session', ' Milestone Cake Smash Session\n\nCelebrate your little one\'s first birthday (or any milestone!) with a fun, messy, and unforgettable cake smash photo session.\n\nIncludes:\n* 1 baby/toddler subject (up to 3 years old)\n* Themed backdrop and balloon setup\n* Cake smash cake (provided or client-supplied)\n* Before and after bath shots\n* 12 edited high-resolution digital photos\n* 1 printed 5R milestone photo\n\nParent or sibling inclusion shots available upon request.', 'Baby & Milestone Photography', 2500.00, 90, '[\"/api/media/MEDIA-7N9BCBP1V\"]', 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,11:00 AM,01:00 PM,03:00 PM', 'Bring a change of clothes for baby,Coordinate balloon and cake color theme with studio,Avoid feeding baby right before the session', '2026-10-02 07:27:20'),
('SRV-ELLA-FAM-01', 'ST-FQKCTCGEL', 'Family Portrait Session', 'Family Portrait Session\n\nA warm and joyful studio portrait session for the whole family ??? capturing the bonds, laughter, and love that make your family unique.\n\nIncludes:\n* Up to 5 family members\n* 1 outfit change\n* Professional studio lighting and backdrop\n* 8 edited high-resolution digital photos\n* 1 printed 8R family portrait\n\nAdditional members may be accommodated with a small surcharge. Advance booking recommended for weekends.', 'Family Photography', 1800.00, 90, '[\"/api/media/MEDIA-3D802WTFL\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,10:30 AM,01:00 PM,03:00 PM', 'Arrive 15 minutes early for preparation,Coordinate outfit colors or theme,Inform studio of number of members when booking', '2026-10-02 07:26:08'),
('SRV-ELLA-FAM-02', 'ST-FQKCTCGEL', 'Extended Family Session', 'Extended Family Portrait\n\nA comprehensive studio session for large family gatherings ??? reunions, anniversaries, or multi-generational portraits that everyone will treasure.\n\nIncludes:\n* 6 to 15 family members\n* 2 group configurations (e.g., full family + subgroups)\n* Professional lighting for large group setups\n* 12 edited high-resolution digital photos\n* 1 printed 10R family group photo\n\nFor more than 15 members, please contact us for a custom quote.', 'Family Photography', 2800.00, 120, '[\"/api/media/MEDIA-3I6DFOFHG\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,01:00 PM', 'Book at least 1 week in advance,Coordinate matching or complementary outfits,Arrive 15 minutes early for group arrangement', '2026-10-02 07:26:08'),
('SRV-ELLA-PORT-01', 'ST-FQKCTCGEL', 'Individual Portrait Session', 'Classic Individual Portrait\n\nA professional studio portrait session tailored for individuals who want clean, polished, and timeless images.\n\nIncludes:\n* 1 subject\n* Up to 2 outfit changes\n* Professional lighting and backdrop selection\n* 5 edited high-resolution digital photos\n* 1 printed 5R portrait\n\nIdeal for professional headshots, social media profiles, and personal branding.', 'Portrait Photography', 800.00, 60, '[\"/api/media/MEDIA-T9M70YVWY\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,10:30 AM,01:00 PM,02:30 PM,04:00 PM', 'Arrive 10 minutes early,Bring your outfit choices,Avoid heavy glitter makeup', '2026-10-02 07:26:08'),
('SRV-ELLA-PORT-02', 'ST-FQKCTCGEL', 'Couple Portrait Session', 'Romantic Couple Portrait\n\nA studio session designed to capture the chemistry and connection between two people.\n\nIncludes:\n* 2 subjects\n* Up to 2 combined outfit or styling changes\n* Variety of backdrops and lighting moods\n* 8 edited high-resolution digital photos\n* 1 printed 5R couple photo\n\nPerfect for anniversaries, pre-nuptial keepsakes, or just celebrating your love.', 'Portrait Photography', 1200.00, 75, '[\"/api/media/MEDIA-TVUL3RY3A\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,10:30 AM,01:00 PM,02:30 PM,04:00 PM', 'Arrive 10 minutes early,Coordinate outfit colors,Minimal accessories recommended', '2026-10-02 07:26:08'),
('SRV-ELLA-PRD-01', 'ST-FQKCTCGEL', 'Product Still Photography', '???? Product Still Photography\n\nClean, sharp, and commerce-ready product photos on a white or solid-color background ??? ideal for online shops, catalogs, and social media.\n\nIncludes:\n* Up to 10 product items per session\n* White, black, or solid backdrop options\n* Flat lay and upright angle shots\n* 10 edited high-resolution digital photos\n* Delivered via digital download\n\nPerfect for e-commerce sellers, small businesses, and brand launches.', 'Product Photography', 1500.00, 60, '[\"/api/media/MEDIA-IFFSY6AXR\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,10:30 AM,01:00 PM,02:30 PM', 'Bring products clean and ready to shoot,Confirm backdrop color preference before session,Products with fragile packaging must be handled by client', '2026-10-02 07:26:08'),
('SRV-ELLA-PRD-02', 'ST-FQKCTCGEL', 'Lifestyle Product Session', 'Lifestyle Product Photography\n\nContextual product photos in styled settings ??? showing your product in use or in an aspirational scene that connects with your target audience.\n\nIncludes:\n* Up to 5 product items per session\n* Styled set design and prop sourcing (basic)\n* Model or hands-on product usage shots available\n* 10 edited high-resolution digital photos\n* Delivered via digital download\n\nGreat for food products, beauty items, apparel accessories, and gifts.', 'Product Photography', 2500.00, 90, '[\"/api/media/MEDIA-FO8R6AOMK\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,01:00 PM,03:00 PM', 'Send product reference photos at least 3 days before,Bring extra product units if available,Confirm styling direction during booking', '2026-10-02 07:26:08'),
('SRV-ELLA-WED-01', 'ST-FQKCTCGEL', 'Pre-Wedding Studio Session', 'Pre-Wedding Studio Portrait\n\nA styled studio session for couples before the big day ??? capturing excitement, love, and anticipation in a beautifully lit environment.\n\nIncludes:\n* 2 subjects (couple)\n* Up to 2 outfit changes\n* Professional backdrop and lighting setup\n* 10 edited high-resolution digital photos\n* 1 printed 8R couple photo\n\nImages are perfect for invitation cards, save-the-date posts, and pre-wedding displays.', 'Wedding Photography', 2500.00, 90, '[\"/api/media/MEDIA-TET0BB5HU\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,01:00 PM,03:00 PM', 'Booking deposit required,Schedule consultation at least 1 week in advance,Bring outfit and accessory choices', '2026-10-02 07:26:08'),
('SRV-ELLA-WED-02', 'ST-FQKCTCGEL', 'Bridal Portrait Session', ' Bridal Portrait Session\n\nAn elegant studio session exclusively for the bride ??? perfect for bridal preparation photos, gown features, and pre-wedding memories.\n\nIncludes:\n* 1 subject (bride)\n* Up to 2 gown or styling changes\n* Soft romantic lighting setups\n* 10 edited high-resolution digital photos\n* 2 printed 5R bridal portraits\n\nA timeless keepsake celebrating you on your special journey.', 'Wedding Photography', 3000.00, 90, '[\"/api/media/MEDIA-JPYSTFXNM\"]', 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,12:00 PM,02:30 PM', 'Booking deposit required,Hair and makeup must be done before session,Bring your gown and accessories', '2026-10-02 07:26:08'),
('SRV-FDL-01', 'ST-FOODLENS1', 'Menu Photography Session', 'Restaurant Menu Photography\n\nClean, appetizing, and professionally lit food photos for your restaurant menu.\n\nIncludes:\n* Up to 12 menu items per session\n* White and wood surface styling options\n* Top-down and 45-degree angle shots\n* 12 edited high-resolution digital photos\n* Delivered within 3 business days\n\nIdeal for restaurant menus, food delivery apps, and social media posting.', 'Food & Beverage Photography', 2000.00, 120, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,11:00 AM,01:00 PM,03:00 PM', 'Food must arrive fresh and ready to plate,Bring extra portions of hero items,Confirm plating style and surface preference before session', '2026-10-02 08:39:17'),
('SRV-FDL-02', 'ST-FOODLENS1', 'Styled Food Editorial', 'Styled Food Editorial Shoot\n\nA high-concept food photography session with full prop styling, surface sourcing, and creative art direction.\n\nIncludes:\n* Up to 5 hero dish or product setups\n* Full prop and surface styling by our team\n* Editorial and lifestyle angles\n* 15 edited high-resolution digital photos\n* Commercial usage rights included\n\nPerfect for food brands, cafes, catering businesses, and cookbook shoots.', 'Food & Beverage Photography', 4500.00, 240, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,01:00 PM', 'Submit mood board or reference photos at least 3 days before,Bring 2 extra portions of each hero dish,Confirm prop color palette and styling direction', '2026-10-02 08:39:18'),
('SRV-FDL-03', 'ST-FOODLENS1', 'Beverage & Drinks Shoot', 'Beverage & Drinks Photography\n\nA specialized studio session for drinks, cocktails, juices, coffee, and beverages ??? capturing condensation, color, and pour action shots.\n\nIncludes:\n* Up to 8 drink items or varieties\n* Ice, pour, and splash action shots available\n* Backlit and top-down compositions\n* 10 edited high-resolution digital photos\n* Delivered within 3 business days\n\nMake every sip look irresistible.', 'Food & Beverage Photography', 2500.00, 120, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '09:00 AM,11:00 AM,01:00 PM,03:00 PM', 'Bring drinks chilled and ready to serve,Bring 3 portions of each hero drink,Confirm if ice or pour action shots are desired', '2026-10-02 08:39:18'),
('SRV-FSH-01', 'ST-FASHPHOTO', 'Model Portfolio Shoot', '???? Model Portfolio Shoot\n\nA professional portfolio shoot designed to build or refresh your modeling book with versatile, high-impact images.\n\nIncludes:\n* Up to 3 outfit and styling changes\n* Commercial, editorial, and fashion-forward looks\n* Various backdrop and lighting setups\n* 15 edited high-resolution digital photos\n* Delivered within 5 business days\n\nBeginner-friendly ??? our team will guide you through every pose and expression.', 'Fashion & Editorial Photography', 3500.00, 150, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '10:00 AM,01:00 PM,04:00 PM', 'Arrive with base makeup done,Bring outfit options ??? minimum 3 looks,Hair must be styled before arrival,No excessive perfume or cologne on set', '2026-10-02 08:34:54'),
('SRV-FSH-02', 'ST-FASHPHOTO', 'Brand Lookbook Shoot', '???? Brand Lookbook Photography\n\nHigh-fashion, editorial-quality images for clothing brands, designers, and boutiques ??? bringing your collection to life on the page and screen.\n\nIncludes:\n* Up to 5 outfit looks per model\n* 1 model (additional models billed separately)\n* Styled backdrop and lighting for each look\n* 20 edited high-resolution digital photos\n* Usage rights for commercial and digital publishing\n\nDelivered within 7 business days.', 'Fashion & Editorial Photography', 6000.00, 240, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday', '10:00 AM,02:00 PM', 'Pre-shoot creative brief required,All garments must be steamed or ironed before arrival,Confirm model details when booking,Usage rights limited to agreed scope', '2026-10-02 08:34:54'),
('SRV-FSH-03', 'ST-FASHPHOTO', 'Creative Concept Editorial', '???? Creative Concept Editorial Shoot\n\nCollaborate with our team on a bold, conceptual editorial ??? from fantasy and avant-garde to retro-chic and minimalist art direction.\n\nIncludes:\n* Full concept consultation session\n* Custom set design and prop sourcing\n* Hair and makeup artist (basic)\n* 1 subject, up to 4 styled looks\n* 20 edited high-resolution digital photos\n\nPerfect for social media content, magazine submissions, and personal branding.', 'Fashion & Editorial Photography', 8000.00, 300, NULL, 1, 'Wednesday,Thursday,Friday,Saturday', '10:00 AM,02:00 PM', 'Pre-shoot concept consultation mandatory,Creative brief must be submitted 1 week before,All concept materials discussed and approved in advance', '2026-10-02 08:34:54'),
('SRV-LMN-01', 'ST-LUMINOS01', 'Birthday Debut Coverage', '???? Birthday Debut Coverage\n\nFull studio portrait coverage for debut and birthday celebrations ??? capturing the magic of the occasion from preparation to the last dance.\n\nIncludes:\n* Up to 4 hours of studio portrait time\n* Solo, group, and candid portraits\n* 18 Roses / 18 Candles styled shots\n* 25 edited high-resolution digital photos\n* Online gallery within 5 business days\n\nPerfect for 18th birthdays, 7th birthdays, and milestone celebrations.', 'Events Photography', 3500.00, 240, NULL, 1, 'Friday,Saturday,Sunday', '09:00 AM,01:00 PM,04:00 PM', 'Book at least 2 weeks in advance,Provide event program or timeline,Coordinate with venue coordinator', '2026-10-02 08:34:54'),
('SRV-LMN-02', 'ST-LUMINOS01', 'Corporate Event Studio Portraits', '???? Corporate Event Studio Portraits\n\nProfessional headshots and team portraits during your corporate event or company gathering.\n\nIncludes:\n* Pop-up studio setup at your venue OR in-studio session\n* Up to 20 individual headshots\n* Team / department group shots\n* 20 edited high-resolution digital photos\n* Delivered within 3 business days\n\nIdeal for company anniversaries, team-building events, and brand launches.', 'Events Photography', 5000.00, 180, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday', '09:00 AM,01:00 PM,03:00 PM', 'Confirm headcount at least 3 days before,Provide dress code or uniform details,On-site setup requires venue approval', '2026-10-02 08:34:54'),
('SRV-LMN-03', 'ST-LUMINOS01', 'Kiddie Party Studio Session', '???? Kiddie Party Studio Session\n\nFun and colorful in-studio portrait session themed for children\'s birthday parties.\n\nIncludes:\n* Up to 2 hours studio time\n* Themed backdrop (balloon, jungle, princess, superhero)\n* Individual and group kids\' portraits\n* Parent-child shots included\n* 15 edited high-resolution digital photos\n\nLet the little ones shine!', 'Events Photography', 2500.00, 120, NULL, 1, 'Saturday,Sunday', '09:00 AM,11:00 AM,01:00 PM,03:00 PM', 'Arrive 15 minutes early for setup,Inform studio of preferred theme,Bring extra outfit for birthday child', '2026-10-02 08:34:54'),
('SRV-PAW-01', 'ST-PETCLICK1', 'Pet Solo Portrait', '???? Pet Solo Portrait Session\n\nA dedicated studio session for one pet ??? letting their personality shine in a professional, comfortable setting.\n\nIncludes:\n* 1 pet subject (dog, cat, rabbit, or small animal)\n* Treat-assisted posing with patient handlers\n* Variety of backdrop colors\n* 10 edited high-resolution digital photos\n* 1 printed 5R pet portrait\n\nFun, stress-free, and always at the pet\'s pace.', 'Pet Photography', 1800.00, 60, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '09:00 AM,11:00 AM,01:00 PM,03:00 PM', 'Pets must be vaccinated and up to date on flea/tick treatment,Bring a favorite toy or treat,Keep pet on leash or in carrier until session begins', '2026-10-02 08:34:55'),
('SRV-PAW-02', 'ST-PETCLICK1', 'Pet & Family Portrait', '???? Pet & Family Portrait Session\n\nA joyful studio session featuring your pet and the humans who love them ??? capturing the bond that makes your family complete.\n\nIncludes:\n* 1 pet + up to 4 family members\n* Mix of pet-solo and group family shots\n* 12 edited high-resolution digital photos\n* 1 printed 8R family-and-pet portrait\n\nBecause pets are family too.', 'Pet Photography', 2800.00, 90, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '09:00 AM,11:00 AM,01:00 PM,03:00 PM', 'Pet vaccination records required,Coordinate outfit colors with family,Bring pet treats and favorite toy', '2026-10-02 08:34:55'),
('SRV-PAW-03', 'ST-PETCLICK1', 'Pet Birthday Bash Session', '???? Pet Birthday Bash Session\n\nCelebrate your furry friend\'s birthday in style with a fun, themed studio session complete with birthday props and cake!\n\nIncludes:\n* Birthday-themed backdrop and balloon setup\n* Pet birthday cake (dog/cat safe, provided by studio)\n* Party hat and bandana styling\n* 12 edited high-resolution digital photos\n* 1 printed 5R birthday portrait\n\nEvery pet deserves a birthday photoshoot!', 'Pet Photography', 2500.00, 75, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '09:00 AM,11:00 AM,01:00 PM,03:00 PM', 'Confirm pet species and size when booking,Bring a change of outfit for pet if desired,Inform studio of any allergies before session', '2026-10-02 08:34:55'),
('SRV-SNC-01', 'ST-SNAPCRAFT', '1-Hour Solo Self-Shoot', '???? 1-Hour Solo Self-Shoot\n\nRent the studio for one hour and shoot to your heart\'s content ??? fully solo or with a friend as your photographer.\n\nIncludes:\n* 1-hour studio access\n* Choice of 1 themed set (cafe, minimalist, neon, garden)\n* Ring light and continuous lighting setup\n* Free use of props and accessories\n* Unlimited shots (you keep all photos)\n\nBring your phone, mirrorless, or DSLR ??? all are welcome.', 'Self-Shoot Studio', 800.00, 60, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '10:00 AM,11:00 AM,12:00 PM,01:00 PM,02:00 PM,03:00 PM,04:00 PM,05:00 PM,06:00 PM,07:00 PM,08:00 PM', 'Socks required on all sets,Maximum 2 people per solo slot,No food or drinks on set', '2026-10-02 08:34:54'),
('SRV-SNC-02', 'ST-SNAPCRAFT', 'Group Self-Shoot (up to 6 pax)', '???? Group Self-Shoot Session\n\nBring your squad! A fun and affordable group studio session where you control the shoot.\n\nIncludes:\n* 2-hour studio access for up to 6 people\n* Access to 2 themed sets\n* Multiple lighting setups available\n* Free props and accessories\n* Unlimited shots (everyone keeps all photos)\n\nGreat for barkada shoots, content creator collabs, and group birthday sessions.', 'Self-Shoot Studio', 1500.00, 120, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '10:00 AM,12:00 PM,02:00 PM,04:00 PM,06:00 PM,08:00 PM', 'Socks required on all sets,Maximum 6 people per group slot,Book in advance for weekends', '2026-10-02 08:34:54'),
('SRV-SNC-03', 'ST-SNAPCRAFT', 'Content Creator Package (Half Day)', '???? Content Creator Half-Day Shoot\n\nA dedicated half-day studio block for serious content creators, vloggers, and influencers.\n\nIncludes:\n* 4-hour studio access (up to 3 people)\n* Access to all available themed sets\n* Full lighting control (strobes, ring lights, LEDs)\n* Wardrobe rack and dressing area access\n* Behind-the-scenes assistance from our studio crew\n* Unlimited shots\n\nCreate a full month\'s worth of content in one session.', 'Self-Shoot Studio', 3000.00, 240, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday', '10:00 AM,02:00 PM,06:00 PM', 'Book at least 2 days in advance,List preferred sets when booking,Maximum 3 people included ??? extra pax at ???200 each', '2026-10-02 08:34:54'),
('SRV-VOW-01', 'ST-COUPLECO1', 'Engagement Studio Session', 'Engagement Studio Session\n\nAn intimate and romantic studio session celebrating your engagement ??? capturing the joy, love, and anticipation of the next chapter.\n\nIncludes:\n* 2 subjects (couple)\n* Up to 2 outfit changes\n* Romantic and modern lighting setups\n* Floral and minimal prop options\n* 12 edited high-resolution digital photos\n* 1 printed 8R engagement portrait\n\nPerfect for save-the-date cards, social announcements, and keepsakes.', 'Wedding Photography', 3000.00, 90, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '10:00 AM,01:00 PM,04:00 PM', 'Book at least 1 week in advance,Coordinate outfit colors ??? avoid clashing patterns,Bring meaningful props (rings, letters, flowers) if desired', '2026-10-02 08:41:26'),
('SRV-VOW-02', 'ST-COUPLECO1', 'Pre-Nuptial Cinematic Session', 'Pre-Nuptial Cinematic Session\n\nA full cinematic pre-wedding studio experience ??? multiple styled scenes, dramatic lighting, and storytelling photography that reads like a film.\n\nIncludes:\n* 2 subjects (couple)\n* Up to 4 styled scene and outfit changes\n* Cinematic, dramatic, and romantic lighting setups\n* 25 edited high-resolution digital photos\n* 1 printed 10R hero couple portrait\n* 2 printed 5R individual portraits\n\nFor couples who want their pre-nuptial photos to look like art.', 'Wedding Photography', 7500.00, 300, NULL, 1, 'Tuesday,Wednesday,Thursday,Friday,Saturday', '10:00 AM,02:00 PM', 'Book at least 2 weeks in advance,Pre-shoot consultation required,Hair and makeup must be done before arrival,Bring all outfits and accessories pressed and ready', '2026-10-02 08:41:26'),
('SRV-VOW-03', 'ST-COUPLECO1', 'Styled Anniversary Session', 'Styled Anniversary Session\n\nCelebrate your years together with a beautifully styled anniversary portrait session ??? a gift to yourselves and a keepsake for the years ahead.\n\nIncludes:\n* 2 subjects (couple)\n* Up to 2 styled looks\n* Anniversary-themed props available\n* 10 edited high-resolution digital photos\n* 1 printed 8R anniversary portrait\n\nAvailable for all anniversaries ??? first, silver, golden, and everything in between.', 'Wedding Photography', 3500.00, 90, NULL, 1, 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday', '10:00 AM,01:00 PM,04:00 PM', 'Inform studio of anniversary milestone when booking,Bring props or items meaningful to your relationship,Coordinate outfits to complement the set', '2026-10-02 08:41:26');
INSERT INTO `studios` (`id`, `name`, `owner_id`, `logo`, `cover_image`, `location`, `rating`, `review_count`, `starting_price`, `categories`, `description`, `address`, `contact_info`, `email`, `business_hours`, `is_approved`, `status`, `printing_available`, `latitude`, `longitude`, `business_permit`, `valid_id`, `other_docs`, `created_at`, `registered_by_admin`, `blocked_dates`, `facebook_url`, `instagram_url`, `tiktok_url`, `other_social_url`, `website_url`, `gcash_number`, `gcash_account_name`, `gcash_qr_code`, `maya_number`, `maya_account_name`, `maya_qr_code`) VALUES
('ST-COUPLECO1', 'The Vow Studio', 'U-VOWSTUDIO', 'https://images.unsplash.com/photo-1519741497674-611481863552?w=256&q=80', 'https://images.unsplash.com/photo-1529636798458-92182e662485?w=1600&q=85', 'Cainta, Rizal', 5.00, 4, 4000.00, 'Wedding Photography,Portrait Photography', 'The Vow Studio is a romantic and intimate photography studio dedicated to couples ??? from the excitement of engagement to the tenderness of pre-nuptial portraits. We tell your love story with artistry, warmth, and timeless elegance.', '2F Ortigas East Tower, Ortigas Ave Extension, Cainta, Rizal 1900', '09221347890', 'info@thevowstudio.ph', '10:00 AM - 07:00 PM', 1, 'approved', 1, 14.591300, 121.122800, 'PERMIT-VOW-2026', 'VALID-ID-VOW-2026', NULL, '2026-10-02 08:39:18', 1, '', 'https://facebook.com/thevowstudio.cainta', 'https://instagram.com/thevowstudio', NULL, NULL, NULL, '09221347890', 'Rafael Cruz - The Vow Studio', NULL, NULL, NULL, NULL),
('ST-FASHPHOTO', 'Frame & Fashion Studio', 'U-FASHPHOTO', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=256&q=80', 'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?w=1600&q=85', 'Cainta, Rizal', 5.00, 3, 2500.00, 'Fashion & Editorial Photography,Portrait Photography', 'Frame & Fashion Studio is the premier fashion and editorial photography studio in Cainta. We work with aspiring and professional models, fashion brands, designers, and creatives to produce striking editorial images, lookbooks, and campaign content.', '3F Estancia Mall, Capitol Commons access via Cainta, Rizal 1900', '09279034512', 'shoot@frameandfashion.ph', '10:00 AM - 08:00 PM', 1, 'approved', 0, 14.590100, 121.121400, 'PERMIT-FASHION-2026', 'VALID-ID-FASHION-2026', NULL, '2026-10-02 08:34:54', 1, '', 'https://facebook.com/frameandfashion.studio', 'https://instagram.com/frameandfashionstudio', NULL, NULL, NULL, '09279034512', 'Adrian Tan - Frame & Fashion', NULL, NULL, NULL, NULL),
('ST-FOODLENS1', 'FoodLens Studio', 'U-FOODLENS', 'https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?w=256&q=80', 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=1600&q=85', 'Cainta, Rizal', 5.00, 3, 2000.00, 'Food & Beverage Photography,Product Photography', 'FoodLens Studio is Cainta\'s specialized food and beverage photography studio. We produce mouthwatering, scroll-stopping images for restaurants, food entrepreneurs, cafes, and food delivery brands. From clean menu shots to elaborate styled food scenes ??? we make food look irresistible.', 'G/F San Juan Commercial Center, Cainta, Rizal 1900', '09663341890', 'studio@foodlens.ph', '09:00 AM - 07:00 PM', 1, 'approved', 0, 14.582500, 121.117300, 'PERMIT-FOODLENS-2026', 'VALID-ID-FOODLENS-2026', NULL, '2026-10-02 08:34:55', 1, '', 'https://facebook.com/foodlensstudio', 'https://instagram.com/foodlensstudio', NULL, NULL, NULL, '09663341890', 'Paulo Mendoza - FoodLens', NULL, NULL, NULL, NULL),
('ST-FQKCTCGEL', 'Ellamaephotstudio ', 'U-A7J5XFMLZ', '/api/media/MEDIA-0LC1U2EI7', '/api/media/MEDIA-VZJ08FNIW', 'San Juan', 4.90, 7, 1000.00, 'Portrait Photography,Graduation Photography,Wedding Photography,Product Photography,Family Photography,Baby & Milestone Photography,Graduation Shoots,Wedding Milestones,Family Portrait,ID/Passport Photography,Event Coverage,Self-Shoot Studio,Product Creative,Baby & Milestone', 'Welcome to our newly registered photography studio! Complete our profile setup to list services, customizable packages, and receive instant bookings.', 'San Juan', '0987865653', 'maelucanas05@gmail.com', '09:00 AM - 06:00 PM', 1, 'approved', 1, 14.593961, 121.129138, '/api/media/MEDIA-8P4RJ9QCW', '/api/media/MEDIA-5D4YELIQN', NULL, '2026-09-30 08:59:36', 0, '', 'https://www.facebook.com/ellamae.lucanas', NULL, NULL, NULL, NULL, '09933435380', 'Ellamae Lucanas', NULL, '09933435380', 'Ellamaephotstudio', NULL),
('ST-LUMINOS01', 'Luminos Studio', 'U-LUMINOS01', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?w=256&q=80', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=1600&q=85', 'Cainta, Rizal', 4.80, 5, 1500.00, 'Events Photography,Family Photography,Portrait Photography', 'Luminos Studio specializes in vibrant events and social gathering photography ??? from intimate birthday parties and debuts to corporate events and family reunions. We bring energy, color, and genuine emotion to every frame.', '2F Rublou Business Center, Felix Avenue, Cainta, Rizal 1900', '09178823341', 'admin@luminosstudio.ph', '09:00 AM - 07:00 PM', 1, 'approved', 1, 14.574120, 121.112340, 'PERMIT-LUMINOS-2026', 'VALID-ID-LUMINOS-2026', NULL, '2026-10-02 08:34:54', 1, '', 'https://facebook.com/luminosstudio.cainta', NULL, NULL, NULL, NULL, '09178823341', 'Marco Reyes - Luminos', NULL, NULL, NULL, NULL),
('ST-MATERNITY1', 'Bloom Maternity Studio', 'U-BLOOM01', 'https://images.unsplash.com/photo-1519689680058-324335c77eba?w=256&q=80', 'https://images.unsplash.com/photo-1555881400-74d7acaacd8b?w=1600&q=85', 'Cainta, Rizal', 4.70, 3, 2000.00, 'Maternity Photography,Baby & Milestone Photography', 'Bloom Maternity Studio is a warm and gentle photography studio dedicated exclusively to maternity, newborn, and baby milestone sessions. Every detail ??? from the soft wraps to the floral setups ??? is crafted to make moms and babies feel safe, celebrated, and beautiful.', 'Unit 3A, San Isidro Commercial Bldg, Cainta, Rizal 1900', '09391827465', 'info@bloommaternity.ph', '09:00 AM - 06:00 PM', 1, 'approved', 1, 14.588700, 121.119200, 'PERMIT-BLOOM-2026', 'VALID-ID-BLOOM-2026', NULL, '2026-10-02 08:34:54', 1, '', 'https://facebook.com/bloommaternity.cainta', 'https://instagram.com/bloommaternity', NULL, NULL, NULL, '09391827465', 'Carla Santos - Bloom', NULL, NULL, NULL, NULL),
('ST-PETCLICK1', 'PawClick Studio', 'U-PETCLICK', 'https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=256&q=80', 'https://images.unsplash.com/photo-1548199973-03cce0bbc87b?w=1600&q=85', 'Cainta, Rizal', 5.00, 3, 1800.00, 'Pet Photography,Family Photography', 'PawClick Studio is a dedicated pet photography studio in Cainta where pets are the stars. Our pet-friendly space is designed to keep animals calm and comfortable while we capture their personality, antics, and adorable moments. Dogs, cats, rabbits, and more are all welcome!', 'Unit 7, Dela Paz Commercial Strip, Cainta, Rizal 1900', '09184567823', 'hello@pawclick.ph', '09:00 AM - 06:00 PM', 1, 'approved', 1, 14.576800, 121.115600, 'PERMIT-PAWCLICK-2026', 'VALID-ID-PAWCLICK-2026', NULL, '2026-10-02 08:34:55', 1, '', 'https://facebook.com/pawclickstudio', 'https://instagram.com/pawclickstudio', NULL, NULL, NULL, '09184567823', 'Trisha Villanueva - PawClick', NULL, NULL, NULL, NULL),
('ST-SNAPCRAFT', 'SnapCraft Studio', 'U-SNAPCRAFT', 'https://images.unsplash.com/photo-1567359781514-3b964e2b04d6?w=256&q=80', 'https://images.unsplash.com/photo-1598300042247-d088f8ab3a91?w=1600&q=85', 'Cainta, Rizal', 5.00, 7, 800.00, 'Self-Shoot Studio,Portrait Photography', 'SnapCraft Studio is Cainta\'s go-to self-shoot studio ??? rent our fully-equipped space by the hour and create content your way. Multiple themed sets, professional lighting, and props ready for you. No photographer needed, just bring your ideas.', 'G/F Cainta Square Mall, Ortigas Ave Ext, Cainta, Rizal 1900', '09552019876', 'hello@snapcraftstudio.ph', '10:00 AM - 10:00 PM', 1, 'approved', 0, 14.580300, 121.118900, 'PERMIT-SNAPCRAFT-2026', 'VALID-ID-SNAPCRAFT-2026', NULL, '2026-10-02 08:34:54', 1, '', 'https://facebook.com/snapcraftstudio', 'https://instagram.com/snapcraftstudio', NULL, NULL, NULL, '09552019876', 'Janine Flores - SnapCraft', NULL, NULL, NULL, NULL);
